/**
 * The photo library: one row per image, and the only place a photo's meaning is recorded.
 *
 * The files themselves are generated by `node scripts/build-media.mjs` from the originals
 * in media-src/ (gitignored). That script owns which source photo becomes which numbered
 * derivative; this file owns what each derivative is *of*.
 *
 * `dir` (taken from the id prefix) is only where the bytes live and never changes.
 * `company` and `category` say where a photo is shown and default to the folder's owner.
 * `tags` say what it depicts, and that is what lets a page ask for exactly the ARGAS photos
 * or exactly the Jaber crossing photos instead of dumping a whole category.
 *
 * To retag: edit a row. To add photos: add them in build-media.mjs, re-run it, append rows.
 */
import type { CompanyId } from './companies';

export type GalleryCategory = 'transport' | 'equipment' | 'camps' | 'catering' | 'projects';

export const GALLERY_CATEGORIES: GalleryCategory[] = [
  'transport',
  'equipment',
  'camps',
  'catering',
  'projects',
];

/** Physical folders under /assets/gallery/. Happen to share the category names today. */
type MediaDir = GalleryCategory;

/**
 * Closed vocabulary, so a typo is a compile error rather than a photo that silently
 * never appears in any strip.
 */
export type MediaTag =
  // Projects
  | 'argas' | 'adnoc' | 'al-jaffr' | 'azraq' | 'sarhan'
  // Border crossings
  | 'jaber' | 'tarbil' | 'al-karamah' | 'al-omari'
  // Subjects
  | 'fleet' | 'flatbed' | 'lowbed' | 'tanker' | 'forklift' | 'crane' | 'winch' | 'loader'
  | 'caravan' | 'kitchen' | 'dining' | 'accommodation' | 'office' | 'workshop' | 'crew'
  | 'night-ops' | 'convoy' | 'loading'
  // Camp welfare and housekeeping
  | 'laundry' | 'ablutions' | 'recreation' | 'hygiene'
  // Context
  | 'border' | 'desert' | 'site' | 'warehouse' | 'amman';

/** Which company a folder's photos belong to unless a row says otherwise. */
const DIR_OWNER: Record<MediaDir, CompanyId> = {
  transport: 'transport',
  equipment: 'project-services',
  camps: 'project-services',
  catering: 'project-services',
  projects: 'project-services',
};

/** A hand-edited row. Everything except `id` is optional and falls back to the folder. */
interface MediaSeed {
  id: string;
  company?: CompanyId;
  category?: GalleryCategory;
  tags?: MediaTag[];
  alt?: { en: string; ar: string };
  /** Good enough to carry a hero or a FeatureSplit, not just a grid tile. */
  featured?: boolean;
}

interface MediaBase {
  id: string;
  dir: MediaDir;
  company: CompanyId;
  category: GalleryCategory;
  tags: MediaTag[];
  alt?: { en: string; ar: string };
  featured: boolean;
  /** 600x600 WebP for the aspect-square grid tile. */
  thumb: string;
}

export interface MediaPhoto extends MediaBase {
  kind: 'photo';
  /** Long edge <= 1600 WebP, fetched only when the lightbox opens. */
  full: string;
}

export interface MediaVideo extends MediaBase {
  kind: 'video';
  src: string;
  poster: string;
  width: number;
  height: number;
}

/** Discriminated on `kind`. Narrow with it before reaching for video-only fields. */
export type MediaItem = MediaPhoto | MediaVideo;

