const dirOf = (id: string) => id.replace(/-\d+$/, '') as MediaDir;

const photos: MediaPhoto[] = SEED.map((seed) => {
  const dir = dirOf(seed.id);
  return {
    id: seed.id,
    dir,
    company: seed.company ?? DIR_OWNER[dir],
    category: seed.category ?? dir,
    tags: seed.tags ?? [],
    alt: seed.alt,
    featured: seed.featured ?? false,
    kind: 'photo',
    thumb: `/assets/gallery/${dir}/${seed.id}-thumb.webp`,
    full: `/assets/gallery/${dir}/${seed.id}.webp`,
  };
});

